===== FILE: index.html =====
<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>观潮新闻 - 洞察时代脉搏 传递中国声音</title>
<style>
:root {
  --brand-red: #c8161d;
  --brand-red-dark: #9e0e14;
  --brand-gold: #d49b27;
  --ink-black: #17191c;
  --ink-gray: #4e5562;
  --muted-gray: #88909e;
  --bg-page: #f4f5f7;
  --bg-card: #ffffff;
  --bg-subtle: #f8f9fb;
  --border-color: #e4e7ed;
  --market-up: #d92626;
  --market-down: #128c55;
  --font-scale: 1;
  --radius-sm: 4px;
  --radius-md: 8px;
  --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.04);
  --shadow-md: 0 6px 20px rgba(0, 0, 0, 0.08);
}

body.dark-mode {
  --ink-black: #eef0f4;
  --ink-gray: #b2b8c4;
  --muted-gray: #78808f;
  --bg-page: #111317;
  --bg-card: #1b1e24;
  --bg-subtle: #232730;
  --border-color: #2e333d;
  --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.3);
  --shadow-md: 0 6px 20px rgba(0, 0, 0, 0.45);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Noto Sans CJK SC", sans-serif;
  background-color: var(--bg-page);
  color: var(--ink-black);
  line-height: 1.65;
  font-size: calc(15px * var(--font-scale));
  transition: background-color 0.25s, color 0.25s;
}

a {
  color: inherit;
  text-decoration: none;
  transition: color 0.2s;
}

a:hover {
  color: var(--brand-red);
}

ul {
  list-style: none;
}

.container {
  max-width: 1220px;
  margin: 0 auto;
  padding: 0 18px;
}

/* 顶部工具栏 */
.top-bar {
  background-color: var(--bg-card);
  border-bottom: 1px solid var(--border-color);
  font-size: 13px;
  color: var(--ink-gray);
}

.top-bar-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 38px;
  flex-wrap: wrap;
  gap: 10px;
}

.top-bar-left,
.top-bar-right {
  display: flex;
  align-items: center;
  gap: 16px;
}

.weather-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--bg-subtle);
  padding: 2px 10px;
  border-radius: 12px;
  border: 1px solid var(--border-color);
}

.util-btn {
  background: var(--bg-subtle);
  border: 1px solid var(--border-color);
  color: var(--ink-gray);
  padding: 3px 10px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  font-size: 12px;
  transition: all 0.2s;
}

.util-btn:hover,
.util-btn.active {
  border-color: var(--brand-red);
  color: var(--brand-red);
}

/* 品牌头部 */
.brand-header {
  background-color: var(--bg-card);
  padding: 20px 0;
}

.brand-header-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  flex-wrap: wrap;
}

.logo-area {
  display: flex;
  align-items: center;
  gap: 14px;
}

.logo-text-wrap {
  display: flex;
  flex-direction: column;
}

.logo-title {
  font-size: 28px;
  font-weight: 800;
  letter-spacing: 2px;
  color: var(--ink-black);
  line-height: 1.15;
}

.logo-subtitle {
  font-size: 12px;
  color: var(--muted-gray);
  letter-spacing: 1px;
  margin-top: 2px;
}

.search-box {
  display: flex;
  align-items: center;
  width: 340px;
  max-width: 100%;
  border: 2px solid var(--brand-red);
  border-radius: var(--radius-sm);
  overflow: hidden;
  background: var(--bg-card);
}

.search-input {
  flex: 1;
  border: none;
  padding: 8px 12px;
  font-size: 14px;
  outline: none;
  background: transparent;
  color: var(--ink-black);
}

.search-btn {
  background: var(--brand-red);
  color: #ffffff;
  border: none;
  padding: 8px 18px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}

.search-btn:hover {
  background: var(--brand-red-dark);
}

/* 主导航 */
.main-nav {
  background: var(--brand-red);
  color: #ffffff;
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: var(--shadow-sm);
}

.nav-list {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
}

.nav-item a {
  display: block;
  padding: 12px 22px;
  color: #ffffff;
  font-weight: 600;
  font-size: 16px;
  letter-spacing: 0.5px;
}

.nav-item a:hover,
.nav-item a.active {
  background: var(--brand-red-dark);
  color: #ffffff;
}

/* 滚动快讯条 */
.ticker-bar {
  background: var(--bg-card);
  border-bottom: 1px solid var(--border-color);
  padding: 10px 0;
  margin-bottom: 20px;
}

.ticker-inner {
  display: flex;
  align-items: center;
  gap: 14px;
}

.ticker-badge {
  background: var(--brand-red);
  color: #ffffff;
  font-size: 12px;
  font-weight: 700;
  padding: 3px 9px;
  border-radius: 3px;
  flex-shrink: 0;
}

.ticker-content {
  flex: 1;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 14px;
}

.ticker-controls {
  display: flex;
  gap: 6px;
}

.ticker-btn {
  background: var(--bg-subtle);
  border: 1px solid var(--border-color);
  color: var(--ink-gray);
  width: 24px;
  height: 24px;
  border-radius: 3px;
  cursor: pointer;
  font-size: 12px;
}

/* 头条横幅 */
.headline-banner {
  background: var(--bg-card);
  border-radius: var(--radius-md);
  padding: 22px 26px;
  margin-bottom: 22px;
  border-top: 4px solid var(--brand-red);
  box-shadow: var(--shadow-sm);
}

.headline-tag {
  display: inline-block;
  color: var(--brand-red);
  border: 1px solid var(--brand-red);
  font-size: 12px;
  font-weight: 700;
  padding: 1px 8px;
  border-radius: 3px;
  margin-bottom: 8px;
}

.headline-title {
  font-size: calc(26px * var(--font-scale));
  font-weight: 800;
  line-height: 1.35;
  margin-bottom: 10px;
}

.headline-sublinks {
  display: flex;
  flex-wrap: wrap;
  gap: 18px;
  font-size: 14px;
  color: var(--ink-gray);
}

.headline-sublinks a::before {
  content: "▪ ";
  color: var(--brand-red);
}

/* 主体两栏布局 */
.main-layout {
  display: grid;
  grid-template-columns: 1fr 350px;
  gap: 24px;
  margin-bottom: 36px;
}

@media (max-width: 960px) {
  .main-layout {
    grid-template-columns: 1fr;
  }
}

/* 焦点大图卡片 */
.hero-grid {
  display: grid;
  grid-template-columns: 1.35fr 1fr;
  gap: 16px;
  margin-bottom: 24px;
}

@media (max-width: 720px) {
  .hero-grid {
    grid-template-columns: 1fr;
  }
}

.hero-main-card {
  position: relative;
  border-radius: var(--radius-md);
  overflow: hidden;
  background: #102542;
  color: #ffffff;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  min-height: 310px;
  box-shadow: var(--shadow-sm);
}

.hero-svg-bg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hero-overlay {
  position: relative;
  z-index: 2;
  background: linear-gradient(to top, rgba(10, 16, 28, 0.94) 15%, rgba(10, 16, 28, 0.2) 100%);
  padding: 22px;
}

.hero-overlay-tag {
  background: var(--brand-red);
  color: #ffffff;
  font-size: 12px;
  padding: 2px 8px;
  border-radius: 3px;
  display: inline-block;
  margin-bottom: 8px;
}

.hero-overlay h2 {
  font-size: calc(20px * var(--font-scale));
  line-height: 1.4;
  margin-bottom: 6px;
}

.hero-overlay h2 a {
  color: #ffffff;
}

.hero-overlay p {
  font-size: 13px;
  color: #d0d7e2;
}

.hero-side-stack {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.hero-mini-card {
  background: var(--bg-card);
  border-radius: var(--radius-md);
  padding: 16px;
  border: 1px solid var(--border-color);
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.hero-mini-cat {
  font-size: 12px;
  font-weight: 700;
  color: var(--brand-red);
  margin-bottom: 4px;
}

.hero-mini-title {
  font-size: calc(16px * var(--font-scale));
  font-weight: 700;
  line-height: 1.45;
  margin-bottom: 6px;
}

.hero-mini-meta {
  font-size: 12px;
  color: var(--muted-gray);
}

/* 分类筛选新闻流 */
.feed-section {
  background: var(--bg-card);
  border-radius: var(--radius-md);
  padding: 20px;
  box-shadow: var(--shadow-sm);
}

.feed-tabs {
  display: flex;
  gap: 10px;
  border-bottom: 2px solid var(--border-color);
  padding-bottom: 12px;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

.feed-tab-btn {
  background: transparent;
  border: none;
  font-size: 15px;
  font-weight: 600;
  color: var(--ink-gray);
  padding: 6px 14px;
  border-radius: var(--radius-sm);
  cursor: pointer;
}

.feed-tab-btn.active,
.feed-tab-btn:hover {
  background: var(--brand-red);
  color: #ffffff;
}

.news-item {
  display: grid;
  grid-template-columns: 180px 1fr;
  gap: 18px;
  padding: 18px 0;
  border-bottom: 1px solid var(--border-color);
}

.news-item:last-child {
  border-bottom: none;
}

@media (max-width: 600px) {
  .news-item {
    grid-template-columns: 1fr;
  }
}

.news-thumb {
  width: 100%;
  height: 112px;
  border-radius: var(--radius-sm);
  overflow: hidden;
  background: var(--bg-subtle);
}

.news-thumb svg {
  width: 100%;
  height: 100%;
  display: block;
}

.news-info {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.news-title {
  font-size: calc(17px * var(--font-scale));
  font-weight: 700;
  line-height: 1.4;
  margin-bottom: 6px;
}

.news-summary {
  font-size: calc(14px * var(--font-scale));
  color: var(--ink-gray);
  margin-bottom: 10px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.news-meta {
  display: flex;
  align-items: center;
  gap: 14px;
  font-size: 12px;
  color: var(--muted-gray);
}

.meta-tag {
  color: var(--brand-red);
  background: rgba(200, 22, 29, 0.08);
  padding: 1px 7px;
  border-radius: 3px;
  font-weight: 600;
}

/* 区域新闻切换面板 */
.region-panel {
  background: var(--bg-card);
  border-radius: var(--radius-md);
  padding: 20px;
  margin-top: 24px;
  box-shadow: var(--shadow-sm);
}

.panel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
  flex-wrap: wrap;
  gap: 10px;
}

.panel-title {
  font-size: 18px;
  font-weight: 800;
  padding-left: 10px;
  border-left: 4px solid var(--brand-red);
}

.region-tabs {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.region-btn {
  background: var(--bg-subtle);
  border: 1px solid var(--border-color);
  color: var(--ink-gray);
  padding: 4px 10px;
  border-radius: 3px;
  font-size: 13px;
  cursor: pointer;
}

.region-btn.active {
  background: var(--brand-red);
  color: #ffffff;
  border-color: var(--brand-red);
}

.region-list {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px 24px;
}

@media (max-width: 640px) {
  .region-list {
    grid-template-columns: 1fr;
  }
}

.region-item {
  font-size: 14px;
  padding: 6px 0;
  border-bottom: 1px dashed var(--border-color);
  display: flex;
  justify-content: space-between;
  gap: 10px;
}

.region-city {
  color: var(--brand-red);
  font-weight: 600;
  flex-shrink: 0;
}

/* 右侧边栏 */
.sidebar-col {
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.side-widget {
  background: var(--bg-card);
  border-radius: var(--radius-md);
  padding: 18px;
  box-shadow: var(--shadow-sm);
}

.widget-title {
  font-size: 17px;
  font-weight: 800;
  padding-left: 10px;
  border-left: 4px solid var(--brand-red);
  margin-bottom: 14px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.widget-more {
  font-size: 12px;
  font-weight: 400;
  color: var(--muted-gray);
}

/* 市场速览小组件 */
.market-mini-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.market-mini-box {
  background: var(--bg-subtle);
  border: 1px solid var(--border-color);
  padding: 10px 12px;
  border-radius: var(--radius-sm);
}

.m-name {
  font-size: 12px;
  color: var(--ink-gray);
}

.m-val {
  font-size: 18px;
  font-weight: 800;
  margin: 2px 0;
}

.m-chg {
  font-size: 12px;
  font-weight: 600;
}

.up {
  color: var(--market-up);
}

.down {
  color: var(--market-down);
}

/* 热榜列表 */
.hot-rank-list li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 9px 0;
  border-bottom: 1px solid var(--border-color);
  font-size: 14px;
}

.hot-rank-list li:last-child {
  border-bottom: none;
}

.rank-num {
  width: 20px;
  height: 20px;
  border-radius: 3px;
  background: var(--bg-subtle);
  color: var(--ink-gray);
  font-size: 12px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  margin-top: 2px;
}

.rank-num.top-3 {
  background: var(--brand-red);
  color: #ffffff;
}

/* 24小时快讯时间轴 */
.flash-timeline {
  border-left: 2px solid var(--border-color);
  margin-left: 6px;
  padding-left: 14px;
}

.flash-item {
  position: relative;
  margin-bottom: 14px;
}

.flash-item:last-child {
  margin-bottom: 0;
}

.flash-item::before {
  content: "";
  position: absolute;
  left: -19px;
  top: 6px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--brand-red);
}

.flash-time {
  font-size: 12px;
  color: var(--brand-red);
  font-weight: 700;
}

.flash-text {
  font-size: 13px;
  color: var(--ink-black);
  margin-top: 2px;
}

/* 底部页脚 */
.site-footer {
  background: #181a1f;
  color: #9ca3af;
  padding: 36px 0 28px;
  font-size: 13px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 28px;
  padding-bottom: 24px;
  border-bottom: 1px solid #2d3139;
  margin-bottom: 20px;
}

@media (max-width: 768px) {
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
}

.footer-col h4 {
  color: #ffffff;
  font-size: 15px;
  margin-bottom: 12px;
}

.footer-col ul li {
  margin-bottom: 8px;
}

.footer-col a {
  color: #9ca3af;
}

.footer-col a:hover {
  color: #ffffff;
}

.footer-bottom {
  text-align: center;
  line-height: 1.8;
  color: #717885;
}
</style>
</head>
<body>

<!-- 顶部工具栏 -->
<div class="top-bar">
  <div class="container top-bar-inner">
    <div class="top-bar-left">
      <span>2026年5月18日 星期一（农历丙午年四月初二）</span>
      <span class="weather-pill">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#d49b27" stroke-width="2">
          <circle cx="12" cy="12" r="5"/>
          <path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/>
        </svg>
        北京 晴 26℃ · 空气质量优
      </span>
    </div>
    <div class="top-bar-right">
      <button class="util-btn" id="fontBtn" type="button">字号：标准</button>
      <button class="util-btn" id="themeBtn" type="button">夜间模式</button>
      <a href="article.html#culture">数字报刊</a>
    </div>
  </div>
</div>

<!-- 品牌与搜索 -->
<header class="brand-header">
  <div class="container brand-header-inner">
    <a href="index.html" class="logo-area">
      <svg width="48" height="48" viewBox="0 0 52 52">
        <rect width="52" height="52" rx="10" fill="#c8161d"/>
        <path d="M10 34 C18 24, 26 24, 34 34 C38 38, 42 36, 44 32" stroke="#ffffff" stroke-width="3.5" fill="none" stroke-linecap="round"/>
        <path d="M8 25 C18 14, 28 14, 38 25 C41 28, 44 27, 46 24" stroke="#ffd666" stroke-width="3" fill="none" stroke-linecap="round"/>
      </svg>
      <div class="logo-text-wrap">
        <span class="logo-title">观潮新闻</span>
        <span class="logo-subtitle">洞察时代脉搏 · 传递中国声音</span>
      </div>
    </a>

    <form class="search-box" id="searchForm">
      <input type="text" class="search-input" id="searchInput" placeholder="搜索要闻：长三角高铁、商业航天、以旧换新..." aria-label="站内搜索">
      <button type="submit" class="search-btn">搜索</button>
    </form>
  </div>
</header>

<!-- 主导航 -->
<nav class="main-nav" aria-label="主导航">
  <div class="container">
    <ul class="nav-list">
      <li class="nav-item"><a href="index.html" class="active">首页要闻</a></li>
      <li class="nav-item"><a href="finance.html">财经与市场</a></li>
      <li class="nav-item"><a href="tech.html">科技与创新</a></li>
      <li class="nav-item"><a href="culture.html">文化与生活</a></li>
      <li class="nav-item"><a href="article.html#rail">深度调查</a></li>
    </ul>
  </div>
</nav>

<!-- 滚动快讯条 -->
<div class="ticker-bar">
  <div class="container ticker-inner">
    <span class="ticker-badge">即时快讯</span>
    <div class="ticker-content" id="tickerText">
      <a href="article.html#rail">【交通】长三角超级环线高铁今日迎客流高峰，单日发送旅客突破16.8万人次</a>
    </div>
    <div class="ticker-controls">
      <button class="ticker-btn" id="prevTicker" type="button" aria-label="上一条">‹</button>
      <button class="ticker-btn" id="nextTicker" type="button" aria-label="下一条">›</button>
    </div>
  </div>
</div>

<main class="container">
  <!-- 头条通栏 -->
  <section class="headline-banner">
    <span class="headline-tag">今日社论 · 高质量发展一线观察</span>
    <h1 class="headline-title">
      <a href="article.html#rail">时速350公里穿行江浙沪皖：长三角“超级环线”如何重塑区域科创与产业版图？</a>
    </h1>
    <div class="headline-sublinks">
      <a href="article.html#market">超长期特别国债赋能工业设备更新，智能制造订单同比增长34%</a>
      <a href="article.html#port">宁波舟山港前四月集装箱吞吐量创新高，新能源车出海航线再扩容</a>
      <a href="tech.html">国产低轨宽带通信卫星星座完成组网测试，偏远山区实现毫秒级互联</a>
    </div>
  </section>

  <div class="main-layout">
    <!-- 左侧主内容列 -->
    <div class="primary-col">
      <!-- 视觉焦点区 -->
      <div class="hero-grid">
        <article class="hero-main-card">
