    themeBtn.textContent = '日间模式';
  }
  const savedFont = localStorage.getItem('guanchao_font') || '1';
  document.documentElement.style.setProperty('--font-scale', savedFont);
  fontBtn.textContent = savedFont === '1' ? '字号：标准' : (savedFont === '1.12' ? '字号：大字' : '字号：特大');

  themeBtn.addEventListener('click', function() {
    document.body.classList.toggle('dark-mode');
    const isDark = document.body.classList.contains('dark-mode');
    localStorage.setItem('guanchao_theme', isDark ? 'dark' : 'light');
    themeBtn.textContent = isDark ? '日间模式' : '夜间模式';
  });

  fontBtn.addEventListener('click', function() {
    const cur = localStorage.getItem('guanchao_font') || '1';
    const next = cur === '1' ? '1.12' : (cur === '1.12' ? '1.22' : '1');
    localStorage.setItem('guanchao_font', next);
    document.documentElement.style.setProperty('--font-scale', next);
    fontBtn.textContent = next === '1' ? '字号：标准' : (next === '1.12' ? '字号：大字' : '字号：特大');
